import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  AlertTriangle, CheckCircle, XCircle, RefreshCw, Search,
  ChevronRight, X, MessageSquare, Shield, Loader2, Info, FileText,
} from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { writeAuditLog, writeOutboxEvent } from '@/lib/auditLog';
import { useAuth } from '@/contexts/AuthContext';

// ── Types ──────────────────────────────────────────────────────────────────
type DisputeState = 'open' | 'needs_more_info' | 'resolved' | 'canceled';

type Dispute = {
  id: string;
  match_id: string;
  reason: string;
  state: DisputeState;
  due_by: string | null;
  resolution: string | null;
  notes: string | null;
  resolved_at: string | null;
  created_at?: string;
  opened_by_profile?: { username: string; avatar_url: string | null } | null;
  resolved_by_profile?: { username: string } | null;
  match?: { round: number; tournaments: { name: string; games: { name: string; icon: string } | null } | null } | null;
};

type Evidence = {
  id: string;
  kind: string;
  object_key: string;
  sha256: string;
  phash: string | null;
  created_at: string;
  user?: { username: string } | null;
};

// ── Status meta ────────────────────────────────────────────────────────────
const STATE_META: Record<DisputeState, { label: string; icon: React.ElementType; color: string; bg: string }> = {
  open            : { label: 'Open',             icon: AlertTriangle, color: 'text-red-400',    bg: 'bg-red-500/12 border-red-500/25'    },
  needs_more_info : { label: 'Needs More Info',  icon: Info,          color: 'text-yellow-400', bg: 'bg-yellow-500/12 border-yellow-500/25' },
  resolved        : { label: 'Resolved',         icon: CheckCircle,   color: 'text-green-400',  bg: 'bg-green-500/12 border-green-500/25' },
  canceled        : { label: 'Canceled',         icon: XCircle,       color: 'text-white/30',   bg: 'bg-white/5 border-white/10'         },
};

// ── SLA helper ─────────────────────────────────────────────────────────────
function slaColor(due: string | null): string {
  if (!due) return 'text-white/30';
  const hrs = (new Date(due).getTime() - Date.now()) / 3_600_000;
  if (hrs < 0)  return 'text-red-500';
  if (hrs < 4)  return 'text-red-400';
  if (hrs < 24) return 'text-yellow-400';
  return 'text-white/40';
}

// ── Resolve / update modal ─────────────────────────────────────────────────
function ResolveModal(p: {
  dispute: Dispute;
  onClose: () => void;
  onSaved: () => void;
}): React.ReactElement {
  const { user } = useAuth();
  const [newState, setNewState] = useState<DisputeState>(p.dispute.state);
  const [resolution, setResolution] = useState(p.dispute.resolution ?? '');
  const [notes, setNotes] = useState(p.dispute.notes ?? '');
  const [saving, setSaving] = useState(false);

  const save = async () => {
    setSaving(true);
    const updates: Record<string, unknown> = { state: newState, notes };
    if (newState === 'resolved') {
      if (!resolution.trim()) { toast.error('Resolution text is required to resolve.'); setSaving(false); return; }
      updates.resolution = resolution.trim();
      updates.resolved_by = user?.id;
      updates.resolved_at = new Date().toISOString();
    }
    const { error } = await supabase.from('disputes').update(updates as never).eq('id', p.dispute.id);
    if (error) {
      toast.error(error.message);
    } else {
      await writeAuditLog({
        actor_id: user?.id, action: 'dispute.resolve', entity_type: 'dispute', entity_id: p.dispute.id,
        data: { from: p.dispute.state, to: newState, resolution },
      });
      await writeOutboxEvent('dispute.updated', p.dispute.id, { state: newState, match_id: p.dispute.match_id });
      toast.success(`Dispute ${newState}.`);
      p.onSaved();
      p.onClose();
    }
    setSaving(false);
  };

  const inputCls = 'bg-white/5 border-white/10 text-white placeholder:text-white/25 focus:border-cyan-500/50 text-sm';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <motion.div initial={{ opacity: 0, scale: 0.96, y: 10 }} animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.96 }} transition={{ duration: 0.16 }}
        className="w-full max-w-lg bg-card border border-white/10 rounded-2xl shadow-2xl overflow-hidden">
        <div className="flex items-center justify-between px-6 py-4 border-b border-white/8">
          <h2 className="font-orbitron font-bold text-sm text-white flex items-center gap-2">
            <Shield className="w-4 h-4 text-red-400" />Adjudicate Dispute
          </h2>
          <button onClick={p.onClose} className="p-1.5 rounded-lg hover:bg-white/10 text-white/40 hover:text-white"><X className="w-4 h-4" /></button>
        </div>
        <div className="p-6 space-y-4">
          {/* Match info */}
          <div className="p-3 rounded-xl bg-white/4 border border-white/8 text-sm">
            <p className="text-white/60 mb-1">
              {p.dispute.match?.tournaments?.games?.icon} {p.dispute.match?.tournaments?.name ?? '—'} — Round {p.dispute.match?.round}
            </p>
            <p className="text-white/35 text-xs">{p.dispute.reason}</p>
          </div>

          {/* New state */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs text-white/50 uppercase tracking-wider">Decision</label>
            <div className="grid grid-cols-2 gap-2">
              {(['needs_more_info','resolved','canceled','open'] as DisputeState[]).map(s => (
                <button key={s} onClick={() => setNewState(s)}
                  className={'px-3 py-2.5 rounded-xl border text-xs font-semibold transition-all ' +
                    (newState === s ? STATE_META[s].bg + ' ' + STATE_META[s].color : 'border-white/10 text-white/35 hover:border-white/20')}>
                  {STATE_META[s].label}
                </button>
              ))}
            </div>
          </div>

          {/* Resolution (required when resolving) */}
          {newState === 'resolved' && (
            <div className="flex flex-col gap-1.5">
              <label className="text-xs text-white/50 uppercase tracking-wider">Resolution *</label>
              <textarea value={resolution} onChange={e => setResolution(e.target.value)}
                rows={3} placeholder="Explain the resolution…"
                className={inputCls + ' w-full rounded-lg border px-3 py-2 resize-none'} />
            </div>
          )}

          {/* Notes */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs text-white/50 uppercase tracking-wider">Internal Notes</label>
            <textarea value={notes} onChange={e => setNotes(e.target.value)}
              rows={2} placeholder="Optional admin notes (not shown to users)"
              className={inputCls + ' w-full rounded-lg border px-3 py-2 resize-none'} />
          </div>
        </div>
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-white/8">
          <Button variant="ghost" size="sm" onClick={p.onClose} className="text-white/50 text-xs">Cancel</Button>
          <Button size="sm" onClick={save} disabled={saving}
            className="bg-gradient-to-r from-red-500 to-orange-500 text-white text-xs font-bold gap-2">
            {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Shield className="w-3.5 h-3.5" />}
            Save Decision
          </Button>
        </div>
      </motion.div>
    </div>
  );
}

// ── Dispute detail drawer ──────────────────────────────────────────────────
function DisputeDrawer(p: {
  dispute: Dispute;
  onClose: () => void;
  onAdjudicate: () => void;
  onUpdated: () => void;
}): React.ReactElement {
  const [evidence, setEvidence] = useState<Evidence[]>([]);
  const [loadingEv, setLoadingEv] = useState(true);
  const meta = STATE_META[p.dispute.state];
  const Icon = meta.icon;

  useEffect(() => {
    setLoadingEv(true);
    supabase.from('evidence_objects')
      .select('*, user:profiles!user_id(username)')
      .eq('match_id', p.dispute.match_id)
      .order('created_at')
      .then(({ data }) => {
        setEvidence((data as Evidence[]) ?? []);
        setLoadingEv(false);
      });
  }, [p.dispute.match_id]);

  return (
    <motion.div initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }}
      transition={{ type: 'spring', damping: 28, stiffness: 280 }}
      className="fixed top-0 right-0 bottom-0 z-50 w-full sm:w-[420px] max-w-full bg-[#0a0a16]/98 border-l border-white/10 backdrop-blur-2xl flex flex-col shadow-2xl">
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-4 border-b border-white/8 flex-shrink-0">
        <div className="flex items-center gap-3">
          <div className={'w-8 h-8 rounded-xl flex items-center justify-center ' + meta.bg}>
            <Icon className={'w-4 h-4 ' + meta.color} />
          </div>
          <div>
            <p className={'font-orbitron font-bold text-sm ' + meta.color}>{meta.label}</p>
            <p className="text-[10px] text-white/35">{p.dispute.match?.tournaments?.name ?? '—'}</p>
          </div>
        </div>
        <button onClick={p.onClose} className="w-8 h-8 rounded-xl hover:bg-white/8 flex items-center justify-center text-white/35 hover:text-white">
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-5">
        {/* Reason */}
        <div>
          <p className="text-[11px] text-white/30 uppercase tracking-wider font-mono mb-2">Dispute Reason</p>
          <div className="p-3.5 rounded-xl bg-white/4 border border-white/8">
            <p className="text-sm text-white/80">{p.dispute.reason}</p>
          </div>
        </div>

        {/* Opened by */}
        <div className="flex items-center gap-3 text-sm">
          <div className="w-8 h-8 rounded-full bg-gradient-to-br from-cyan-500 to-purple-600 flex items-center justify-center text-xs font-bold text-white">
            {(p.dispute.opened_by_profile?.username ?? 'U')[0]?.toUpperCase()}
          </div>
          <div>
            <p className="text-white/70 text-xs font-semibold">{p.dispute.opened_by_profile?.username ?? 'Unknown'}</p>
            <p className="text-white/30 text-[10px]">Opened dispute</p>
          </div>
          {p.dispute.due_by && (
            <div className="ml-auto text-right">
              <p className={'text-xs font-mono ' + slaColor(p.dispute.due_by)}>
                SLA: {new Date(p.dispute.due_by).toLocaleString()}
              </p>
            </div>
          )}
        </div>

        {/* Resolution */}
        {p.dispute.resolution && (
          <div>
            <p className="text-[11px] text-white/30 uppercase tracking-wider font-mono mb-2">Resolution</p>
            <div className="p-3.5 rounded-xl bg-green-500/8 border border-green-500/20">
              <p className="text-sm text-green-300/80">{p.dispute.resolution}</p>
              {p.dispute.resolved_by_profile && (
                <p className="text-[10px] text-white/30 mt-2">
                  by {p.dispute.resolved_by_profile.username} · {p.dispute.resolved_at ? new Date(p.dispute.resolved_at).toLocaleString() : ''}
                </p>
              )}
            </div>
          </div>
        )}

        {/* Notes */}
        {p.dispute.notes && (
          <div>
            <p className="text-[11px] text-white/30 uppercase tracking-wider font-mono mb-2">Admin Notes</p>
            <div className="p-3 rounded-xl bg-white/4 border border-white/8">
              <p className="text-xs text-white/50">{p.dispute.notes}</p>
            </div>
          </div>
        )}

        {/* Evidence */}
        <div>
          <p className="text-[11px] text-white/30 uppercase tracking-wider font-mono mb-2">
            Evidence ({evidence.length})
          </p>
          {loadingEv ? (
            <div className="h-12 rounded-xl bg-white/5 animate-pulse" />
          ) : evidence.length === 0 ? (
            <div className="p-4 rounded-xl border border-white/8 text-center">
              <FileText className="w-6 h-6 mx-auto text-white/15 mb-2" />
              <p className="text-xs text-white/30">No evidence submitted yet</p>
            </div>
          ) : (
            <div className="space-y-2">
              {evidence.map(ev => (
                <div key={ev.id} className="p-3 rounded-xl bg-white/4 border border-white/8">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs font-semibold text-white/70 capitalize">{ev.kind}</span>
                    <span className="text-[10px] text-white/30">{ev.user?.username ?? '—'}</span>
                  </div>
                  <p className="text-[10px] font-mono text-white/30 truncate">SHA256: {ev.sha256}</p>
                  {ev.phash && <p className="text-[10px] font-mono text-white/25 truncate">pHash: {ev.phash}</p>}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Adjudicate action */}
      {(p.dispute.state === 'open' || p.dispute.state === 'needs_more_info') && (
        <div className="flex-shrink-0 border-t border-white/8 p-4">
          <Button size="sm" onClick={p.onAdjudicate}
            className="w-full bg-gradient-to-r from-red-500 to-orange-500 text-white text-xs font-bold gap-2 h-10">
            <Shield className="w-3.5 h-3.5" />Adjudicate Dispute
          </Button>
        </div>
      )}
    </motion.div>
  );
}

// ── Main ───────────────────────────────────────────────────────────────────
export function AdminDisputes(): React.ReactElement {
  const [disputes, setDisputes] = useState<Dispute[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [stateFilter, setStateFilter] = useState<DisputeState | 'all'>('all');
  const [selected, setSelected] = useState<Dispute | null>(null);
  const [resolving, setResolving] = useState<Dispute | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('disputes')
      .select(`
        *,
        opened_by_profile:profiles!opened_by(username, avatar_url),
        resolved_by_profile:profiles!resolved_by(username),
        match:matches!match_id(round, tournaments(name, games(name, icon)))
      `)
      .order('due_by', { ascending: true, nullsFirst: false });
    if (error) { console.error(error.message); }
    else setDisputes((data as Dispute[]) ?? []);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const filtered = disputes.filter(d => {
    if (stateFilter !== 'all' && d.state !== stateFilter) return false;
    const q = search.toLowerCase();
    return !q
      || (d.match?.tournaments?.name ?? '').toLowerCase().includes(q)
      || d.reason.toLowerCase().includes(q)
      || (d.opened_by_profile?.username ?? '').toLowerCase().includes(q);
  });

  const counts: Record<string, number> = { all: disputes.length };
  (['open','needs_more_info','resolved','canceled'] as DisputeState[]).forEach(s => {
    counts[s] = disputes.filter(d => d.state === s).length;
  });

  return (
    <div className="p-5 sm:p-7 max-w-5xl">
      {/* Header */}
      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}
        className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="font-orbitron text-2xl font-black text-white mb-1">Disputes</h1>
          <p className="text-white/35 text-sm">
            {counts['open'] ?? 0} open · {counts['needs_more_info'] ?? 0} pending info · {counts['resolved'] ?? 0} resolved
          </p>
        </div>
        <div className="flex items-center gap-2">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-white/30" />
            <Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search…"
              className="pl-8 h-9 bg-white/5 border-white/10 text-white placeholder:text-white/25 text-sm w-44" />
          </div>
          <Button variant="ghost" size="sm" onClick={load} disabled={loading} className="text-white/40 hover:text-white h-9 w-9 p-0">
            <RefreshCw className={'w-3.5 h-3.5 ' + (loading ? 'animate-spin' : '')} />
          </Button>
        </div>
      </motion.div>

      {/* State filter pills */}
      <div className="flex items-center gap-2 mb-5 flex-wrap">
        {(['all','open','needs_more_info','resolved','canceled'] as const).map(s => (
          <button key={s} onClick={() => setStateFilter(s)}
            className={'px-3 py-1.5 rounded-full text-[11px] font-semibold transition-all border ' +
              (stateFilter === s
                ? (s === 'all' ? 'bg-white/15 border-white/20 text-white' : STATE_META[s as DisputeState].bg + ' ' + STATE_META[s as DisputeState].color)
                : 'border-white/8 text-white/35 hover:border-white/15 hover:text-white/60')}>
            {s === 'all' ? `All (${counts.all})` : `${STATE_META[s as DisputeState].label} (${counts[s] ?? 0})`}
          </button>
        ))}
      </div>

      {/* List */}
      {loading ? (
        <div className="space-y-2">{[1,2,3].map(i => <div key={i} className="h-20 rounded-xl bg-white/5 animate-pulse" />)}</div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-20">
          <MessageSquare className="w-12 h-12 mx-auto text-white/15 mb-4" />
          <p className="text-white/35 text-sm">{search ? 'No disputes match your search.' : 'No disputes yet — great sign!'}</p>
        </div>
      ) : (
        <div className="space-y-2">
          {filtered.map((d, i) => {
            const meta = STATE_META[d.state];
            const Icon = meta.icon;
            // eslint-disable-next-line react-hooks/purity
            const isUrgent = d.state === "open" && d.due_by && (new Date(d.due_by).getTime() - Date.now()) < 4 * 3_600_000;
            return (
              <motion.div key={d.id} initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
                onClick={() => setSelected(d)}
                className={'p-4 rounded-xl border transition-all cursor-pointer group flex items-start gap-4 ' +
                  (isUrgent ? 'bg-red-500/6 border-red-500/20 hover:border-red-500/35' : 'bg-white/3 border-white/8 hover:border-white/15 hover:bg-white/5')}>
                <div className={'w-9 h-9 rounded-xl border flex items-center justify-center flex-shrink-0 mt-0.5 ' + meta.bg}>
                  <Icon className={'w-4 h-4 ' + meta.color} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <span className="font-semibold text-sm text-white truncate">
                      {d.match?.tournaments?.games?.icon} {d.match?.tournaments?.name ?? '—'}
                      <span className="text-white/35 ml-1.5 font-normal text-xs">Round {d.match?.round}</span>
                    </span>
                    {isUrgent && <span className="text-[10px] bg-red-500/20 text-red-400 border border-red-500/30 px-1.5 py-0.5 rounded-full font-bold">URGENT</span>}
                  </div>
                  <p className="text-xs text-white/45 truncate mb-1">{d.reason}</p>
                  <div className="flex items-center gap-3 text-[11px] text-white/30">
                    <span className={'font-medium ' + meta.color}>{meta.label}</span>
                    <span>by {d.opened_by_profile?.username ?? '—'}</span>
                    {d.due_by && <span className={slaColor(d.due_by)}>Due {new Date(d.due_by).toLocaleDateString()}</span>}
                  </div>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                  {(d.state === 'open' || d.state === 'needs_more_info') && (
                    <button onClick={e => { e.stopPropagation(); setResolving(d); }}
                      className="px-2.5 py-1 rounded-lg bg-red-500/20 hover:bg-red-500/35 text-red-400 text-[10px] font-bold transition-all border border-red-500/25">
                      Adjudicate
                    </button>
                  )}
                  <ChevronRight className="w-4 h-4 text-white/20 group-hover:text-white/50 transition-colors" />
                </div>
              </motion.div>
            );
          })}
        </div>
      )}

      {/* Drawers + Modals */}
      <AnimatePresence>
        {selected && !resolving && (
          <>
            <motion.div key="bd" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              className="fixed inset-0 z-40 bg-black/50" onClick={() => setSelected(null)} />
            <DisputeDrawer
              key="drawer"
              dispute={selected}
              onClose={() => setSelected(null)}
              onAdjudicate={() => setResolving(selected)}
              onUpdated={() => { load(); setSelected(null); }}
            />
          </>
        )}
        {resolving && (
          <ResolveModal key="resolve" dispute={resolving} onClose={() => setResolving(null)}
            onSaved={() => { load(); setSelected(null); setResolving(null); }} />
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
  Tag, Plus, Trash2, RefreshCw, Copy, CheckCircle,
  AlertCircle, Loader2, Users, Calendar, Gift,
} from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Switch } from '@/components/ui/switch';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from '@/components/ui/dialog';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';

type RewardType = 'points' | 'discount' | 'free_entry';

type LoyaltyCode = {
  id: string;
  code: string;
  description: string | null;
  reward_type: RewardType;
  reward_value: number;
  max_uses: number;
  uses_count: number;
  expires_at: string | null;
  is_active: boolean;
  created_at: string;
};

const emptyForm = {
  code: '', description: '', reward_type: 'points' as RewardType,
  reward_value: 100, max_uses: 1, expires_at: '',
};

function generateCode(): string {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  return 'PULSE-' + Array.from({ length: 6 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
}

function rewardLabel(type: RewardType, value: number): string {
  if (type === 'points')     return `+${value} Points`;
  if (type === 'discount')   return `${value}% Off`;
  if (type === 'free_entry') return 'Free Entry';
  return String(value);
}

function rewardColor(type: RewardType): string {
  if (type === 'points')     return 'bg-cyan-500/20 text-cyan-400 border-cyan-500/30';
  if (type === 'discount')   return 'bg-purple-500/20 text-purple-400 border-purple-500/30';
  if (type === 'free_entry') return 'bg-green-500/20 text-green-400 border-green-500/30';
  return 'bg-white/10 text-white/60';
}

export function AdminLoyalty(): React.ReactElement {
  const { profile } = useAuth();
  const [codes, setCodes]   = useState<LoyaltyCode[]>([]);
  const [loading, setLoading] = useState(true);
  const [isOpen, setIsOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [form, setForm]     = useState(emptyForm);
  const [copied, setCopied] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data } = await (supabase.from('loyalty_codes') as never)
      .select('*')
      .order('created_at', { ascending: false });
    setCodes(data ?? []);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const setF = (k: keyof typeof emptyForm, v: string | number) =>
    setForm(prev => ({ ...prev, [k]: v }));

  const handleSave = async () => {
    if (!form.code.trim()) { toast.error('Code is required.'); return; }
    setIsSaving(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error } = await (supabase.from('loyalty_codes') as never).insert({
      code: form.code.trim().toUpperCase(),
      description: form.description || null,
      reward_type: form.reward_type,
      reward_value: form.reward_value,
      max_uses: form.max_uses,
      expires_at: form.expires_at ? new Date(form.expires_at).toISOString() : null,
      created_by: profile?.id ?? null,
    });
    if (error) {
      if (error.code === '23505') toast.error('Code already exists.');
      else toast.error('Failed: ' + error.message);
    } else {
      toast.success('Loyalty code created!');
      setIsOpen(false);
      setForm(emptyForm);
      load();
    }
    setIsSaving(false);
  };

  const toggleActive = async (id: string, current: boolean) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (supabase.from('loyalty_codes') as never).update({ is_active: !current }).eq('id', id);
    setCodes(prev => prev.map(c => c.id === id ? { ...c, is_active: !current } : c));
    toast.success(!current ? 'Code activated' : 'Code deactivated');
  };

  const handleDelete = async (id: string) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (supabase.from('loyalty_codes') as never).delete().eq('id', id);
    setCodes(prev => prev.filter(c => c.id !== id));
    setDeleteId(null);
    toast.success('Code deleted.');
  };

  const copyCode = (code: string) => {
    navigator.clipboard.writeText(code).then(() => {
      setCopied(code);
      toast.success('Copied to clipboard');
      setTimeout(() => setCopied(null), 2000);
    });
  };

  const totalUses = codes.reduce((s, c) => s + c.uses_count, 0);
  const activeCodes = codes.filter(c => c.is_active).length;

  return (
    <div className="p-5 sm:p-7 max-w-7xl space-y-6">
      {/* Header */}
      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}
        className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <h1 className="font-orbitron text-2xl font-black text-white mb-1">Loyalty Codes</h1>
          <p className="text-white/35 text-sm">Create and manage promotional codes for players</p>
        </div>
        <div className="flex gap-2">
          <Button size="sm" variant="ghost" onClick={load} disabled={loading}
            className="text-white/40 hover:text-white hover:bg-white/8 gap-1.5">
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          </Button>
          <Button onClick={() => { setForm({ ...emptyForm, code: generateCode() }); setIsOpen(true); }}
            className="bg-gradient-to-r from-cyan-500 to-purple-600 hover:opacity-90 gap-2 font-bold text-sm">
            <Plus className="w-4 h-4" />New Code
          </Button>
        </div>
      </motion.div>

      {/* KPIs */}
      <div className="grid grid-cols-3 gap-3">
        {[
          { label: 'Total Codes', val: codes.length, Icon: Tag, cls: 'text-cyan-400' },
          { label: 'Active', val: activeCodes, Icon: CheckCircle, cls: 'text-green-400' },
          { label: 'Total Redemptions', val: totalUses, Icon: Users, cls: 'text-purple-400' },
        ].map(({ label, val, Icon, cls }) => (
          <div key={label} className="p-4 rounded-2xl bg-white/4 border border-white/8 flex items-center gap-3">
            <Icon className={`w-5 h-5 ${cls} flex-shrink-0`} />
            <div>
              <div className="font-orbitron text-xl font-black text-white">{val}</div>
              <div className="text-[10px] text-white/35">{label}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Codes list */}
      {loading ? (
        <div className="space-y-2">{[...Array(4)].map((_, i) => <Skeleton key={i} className="h-20 rounded-2xl" />)}</div>
      ) : codes.length === 0 ? (
        <div className="text-center py-20">
          <Gift className="w-12 h-12 text-white/15 mx-auto mb-3" />
          <p className="text-white/30 text-sm">No loyalty codes yet. Create your first one.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {codes.map((c, i) => {
            const pct = c.max_uses > 0 ? Math.round((c.uses_count / c.max_uses) * 100) : 0;
            const exhausted = c.uses_count >= c.max_uses;
            const expired = c.expires_at ? new Date(c.expires_at) < new Date() : false;
            return (
              <motion.div key={c.id} initial={{ opacity: 0, x: -16 }} animate={{ opacity: 1, x: 0 }}
                transition={{ delay: i * 0.04 }}
                className="flex items-center gap-3 p-4 rounded-2xl bg-white/4 border border-white/8 flex-wrap">
                {/* Code */}
                <div className="flex items-center gap-2 min-w-[160px]">
                  <code className="font-mono font-bold text-sm text-white bg-white/8 px-2 py-1 rounded-lg">
                    {c.code}
                  </code>
                  <button onClick={() => copyCode(c.code)}
                    className="text-white/30 hover:text-cyan-400 transition-colors">
                    {copied === c.code
                      ? <CheckCircle className="w-3.5 h-3.5 text-green-400" />
                      : <Copy className="w-3.5 h-3.5" />}
                  </button>
                </div>

                {/* Description */}
                <div className="flex-1 min-w-[120px]">
                  <div className="text-xs text-white/60 truncate">{c.description ?? '—'}</div>
                  {c.expires_at && (
                    <div className={`text-[10px] flex items-center gap-1 mt-0.5 ${expired ? 'text-red-400' : 'text-white/30'}`}>
                      <Calendar className="w-2.5 h-2.5" />
                      {expired ? 'Expired' : `Expires ${formatDistanceToNow(new Date(c.expires_at), { addSuffix: true })}`}
                    </div>
                  )}
                </div>

                {/* Reward */}
                <Badge className={`text-[10px] ${rewardColor(c.reward_type)}`}>
                  {rewardLabel(c.reward_type, c.reward_value)}
                </Badge>

                {/* Usage */}
                <div className="text-xs text-white/40 whitespace-nowrap">
                  {c.uses_count}/{c.max_uses} uses
                  <div className="w-20 h-1 rounded-full bg-white/10 mt-1 overflow-hidden">
                    <div className="h-full rounded-full bg-gradient-to-r from-cyan-500 to-purple-500"
                      style={{ width: `${Math.min(pct, 100)}%` }} />
                  </div>
                </div>

                {/* Status badges */}
                <div className="flex items-center gap-1.5 flex-wrap">
                  {exhausted && <Badge className="text-[10px] bg-red-500/15 text-red-400 border-red-500/25">Exhausted</Badge>}
                  {expired && !exhausted && <Badge className="text-[10px] bg-orange-500/15 text-orange-400 border-orange-500/25">Expired</Badge>}
                </div>

                {/* Active toggle */}
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-white/30">{c.is_active ? 'Active' : 'Off'}</span>
                  <Switch checked={c.is_active} onCheckedChange={() => toggleActive(c.id, c.is_active)}
                    className="scale-75" />
                </div>

                {/* Delete */}
                <button onClick={() => setDeleteId(c.id)}
                  className="p-1.5 rounded-lg bg-white/5 hover:bg-red-500/15 text-white/25 hover:text-red-400 transition-all">
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </motion.div>
            );
          })}
        </div>
      )}

      {/* Create dialog */}
      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent className="glass border-border/50 max-w-md">
          <DialogHeader>
            <DialogTitle className="font-orbitron">New Loyalty Code</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div>
              <Label className="text-xs">Code *</Label>
              <div className="flex gap-2 mt-1">
                <Input value={form.code} onChange={e => setF('code', e.target.value.toUpperCase())}
                  className="font-mono uppercase" placeholder="PULSE-XXXXXX" />
                <Button size="sm" variant="outline" onClick={() => setF('code', generateCode())}
                  className="whitespace-nowrap text-xs border-white/15 text-white/50 hover:text-white">
                  Generate
                </Button>
              </div>
            </div>
            <div>
              <Label className="text-xs">Description</Label>
              <Input value={form.description} onChange={e => setF('description', e.target.value)}
                className="mt-1" placeholder="Weekend promo code" />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs">Reward Type</Label>
                <Select value={form.reward_type} onValueChange={v => setF('reward_type', v)}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="points">Points</SelectItem>
                    <SelectItem value="discount">Discount %</SelectItem>
                    <SelectItem value="free_entry">Free Entry</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-xs">
                  {form.reward_type === 'points' ? 'Points Amount' : form.reward_type === 'discount' ? 'Discount %' : 'Value'}
                </Label>
                <Input type="number" value={form.reward_value}
                  onChange={e => setF('reward_value', Number(e.target.value))}
                  className="mt-1" min={1} />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs">Max Uses</Label>
                <Input type="number" value={form.max_uses}
                  onChange={e => setF('max_uses', Number(e.target.value))}
                  className="mt-1" min={1} />
              </div>
              <div>
                <Label className="text-xs">Expires At (optional)</Label>
                <Input type="datetime-local" value={form.expires_at}
                  onChange={e => setF('expires_at', e.target.value)}
                  className="mt-1" />
              </div>
            </div>
          </div>
          <DialogFooter className="gap-2">
            <Button variant="outline" onClick={() => setIsOpen(false)}>Cancel</Button>
            <Button onClick={handleSave} disabled={isSaving}
              className="bg-gradient-to-r from-cyan-500 to-purple-600 gap-1.5">
              {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
              Create
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete confirm */}
      <Dialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <DialogContent className="glass border-border/50 max-w-sm">
          <DialogHeader>
            <DialogTitle className="font-orbitron flex items-center gap-2 text-destructive">
              <AlertCircle className="w-5 h-5" />Delete Code
            </DialogTitle>
          </DialogHeader>
          <p className="text-muted-foreground text-sm">
            This will permanently delete the loyalty code and all its redemption history.
          </p>
          <DialogFooter className="gap-2">
            <Button variant="outline" onClick={() => setDeleteId(null)}>Cancel</Button>
            <Button variant="destructive" onClick={() => deleteId && handleDelete(deleteId)}>Delete</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useParams, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  Trophy, Users, Play, CheckCircle, RefreshCw,
  Loader2, UserX, UserCheck, Layers,
  Flag, Crown, Eye,
} from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { writeAuditLog } from '@/lib/auditLog';
import { useAuth } from '@/contexts/AuthContext';

type Tournament = {
  id: string; name: string; status: string; bracket_generated: boolean;
  total_rounds: number | null; current_round: number; max_players: number;
  entry_fee: number; prize_amount: number; easy_mode: boolean;
  games: { name: string; icon: string } | null;
};
type Participant = {
  id: string; user_id: string; status: string; seed: number | null;
  in_game_username: string | null; eliminated_round: number | null;
  profiles: { username: string; avatar_url: string | null } | null;
};
type Match = {
  id: string; round: number; status: string; match_number: number | null;
  player1_id: string | null; player2_id: string | null; winner_id: string | null;
  is_bye: boolean;
  player1: { username: string } | null;
  player2: { username: string } | null;
};
type Dispute = {
  id: string; match_id: string; reason: string; state: string;
  created_at: string; due_by: string | null;
  opened_by_profile: { username: string } | null;
};

export function AdminTournamentControl() {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [disputes, setDisputes] = useState<Dispute[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'overview'|'participants'|'matches'|'disputes'>('overview');
  const [generatingBracket, setGeneratingBracket] = useState(false);
  const [advancingMatch, setAdvancingMatch] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const [tRes, pRes, mRes, dRes] = await Promise.all([
      supabase.from('tournaments').select('*, games(name, icon)').eq('id', id).single(),
      supabase.from('tournament_participants')
        .select('*, profiles(username, avatar_url)')
        .eq('tournament_id', id).order('joined_at'),
      supabase.from('matches')
        .select('id, round, status, match_number, player1_id, player2_id, winner_id, is_bye, player1:profiles!player1_id(username), player2:profiles!player2_id(username)')
        .eq('tournament_id', id).order('match_number'),
      supabase.from('disputes')
        .select('*, opened_by_profile:profiles!opened_by(username)')
        .in('match_id', (await supabase.from('matches').select('id').eq('tournament_id', id)).data?.map((m: any) => m.id) ?? [])
        .order('created_at', { ascending: false }),
    ]);
    if (!tRes.error) setTournament(tRes.data as Tournament);
    if (!pRes.error) setParticipants((pRes.data as Participant[]) ?? []);
    if (!mRes.error) setMatches((mRes.data as Match[]) ?? []);
    if (!dRes.error) setDisputes((dRes.data as Dispute[]) ?? []);
    setLoading(false);
  }, [id]);

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { load(); }, [load]);

  const generateBracket = async () => {
    if (!id || !user) return;
    setGeneratingBracket(true);
    const { error } = await (supabase as never).rpc('generate_bracket', { p_tournament_id: id });
    if (error) toast.error(error.message);
    else { toast.success('Bracket generated! 🏆'); load(); }
    setGeneratingBracket(false);
  };

  const forceAdvance = async (matchId: string, winnerId: string) => {
    setAdvancingMatch(matchId);
    const { error } = await (supabase as never).rpc('advance_match_winner', {
      p_match_id: matchId, p_winner_id: winnerId,
    });
    if (error) toast.error(error.message);
    else {
      await writeAuditLog({ actor_id: user?.id, action: 'match.status_change', entity_type: 'match', entity_id: matchId, data: { forced_winner: winnerId } });
      toast.success('Winner advanced.');
      load();
    }
    setAdvancingMatch(null);
  };

  const toggleCheckIn = async (p: Participant) => {
    const newStatus = p.status === 'checked_in' ? 'joined' : 'checked_in';
    const update: Record<string, unknown> = { status: newStatus };
    if (newStatus === 'checked_in') update.checked_in_at = new Date().toISOString();
    const { error } = await supabase.from('tournament_participants').update(update as never).eq('id', p.id);
    if (error) toast.error(error.message);
    else { toast.success(`${p.profiles?.username} ${newStatus === 'checked_in' ? 'checked in' : 'unchecked'}`); load(); }
  };

  const eliminatePlayer = async (p: Participant) => {
    const { error } = await supabase.from('tournament_participants').update({ status: 'dropped' } as never).eq('id', p.id);
    if (error) toast.error(error.message);
    else { toast.success(`${p.profiles?.username} removed from bracket.`); load(); }
  };

  const resolveDispute = async (disputeId: string, winnerId: string, matchId: string) => {
    await supabase.from('disputes').update({
      state: 'resolved', resolved_by: user?.id, resolved_at: new Date().toISOString(),
      resolution: 'Admin forced result',
    } as never).eq('id', disputeId);
    await (supabase as never).rpc('advance_match_winner', { p_match_id: matchId, p_winner_id: winnerId });
    await writeAuditLog({ actor_id: user?.id, action: 'dispute.resolve', entity_type: 'dispute', entity_id: disputeId, data: { forced_winner: winnerId, match_id: matchId } });
    toast.success('Dispute resolved. Winner advanced.');
    load();
  };

  const statusColor: Record<string, string> = {
    upcoming: 'text-blue-400', ongoing: 'text-green-400', completed: 'text-white/40',
  };

  if (loading) return (
    <div className="p-8 flex items-center justify-center"><Loader2 className="w-6 h-6 animate-spin text-white/30" /></div>
  );
  if (!tournament) return <div className="p-8 text-white/40">Tournament not found.</div>;

  const checkedIn = participants.filter(p => p.status === 'checked_in').length;
  const activeDisputes = disputes.filter(d => d.state === 'open').length;
  const pendingMatches = matches.filter(m => ['scheduled','in_progress','awaiting_proof','disputed'].includes(m.status) && !m.is_bye).length;

  const TABS = [
    { id: 'overview',     label: 'Overview',   icon: Trophy    },
    { id: 'participants', label: `Players (${participants.length})`, icon: Users },
    { id: 'matches',      label: `Matches (${pendingMatches} active)`, icon: Layers },
    { id: 'disputes',     label: `Disputes${activeDisputes > 0 ? ` (${activeDisputes})` : ''}`, icon: Flag },
  ] as const;

  return (
    <div className="p-5 sm:p-7 max-w-6xl">
      {/* Header */}
      <div className="flex items-start gap-4 mb-6">
        <div className="w-12 h-12 rounded-xl bg-yellow-500/15 flex items-center justify-center flex-shrink-0">
          <Trophy className="w-6 h-6 text-yellow-400" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap mb-1">
            <h1 className="font-orbitron text-xl font-black text-white">{tournament.name}</h1>
            <span className={`text-xs font-bold capitalize ${statusColor[tournament.status] ?? 'text-white/40'}`}>• {tournament.status}</span>
            {tournament.easy_mode && <span className="text-[10px] px-2 py-0.5 rounded-full bg-yellow-500/15 border border-yellow-500/25 text-yellow-400 font-bold">⚡ Easy Mode</span>}
          </div>
          <p className="text-sm text-white/40">{tournament.games?.icon} {tournament.games?.name} · {participants.length}/{tournament.max_players} players</p>
        </div>
        <Link to={`/tournaments/${id}`} target="_blank"
          className="flex-shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-xl border border-white/12 text-white/50 text-xs hover:bg-white/5 transition-all">
          <Eye className="w-3.5 h-3.5" />View Page
        </Link>
      </div>

      {/* KPI row */}
      <div className="grid grid-cols-2 gap-3 mb-6">
        {[
          { label: 'Checked In', val: `${checkedIn}/${participants.length}`, color: 'text-green-400', bg: 'bg-green-500/10 border-green-500/15' },
          { label: 'Active Matches', val: pendingMatches, color: 'text-cyan-400', bg: 'bg-cyan-500/10 border-cyan-500/15' },
          { label: 'Open Disputes', val: activeDisputes, color: activeDisputes > 0 ? 'text-red-400' : 'text-white/35', bg: activeDisputes > 0 ? 'bg-red-500/10 border-red-500/15' : 'bg-white/5 border-white/8' },
          { label: 'Round', val: tournament.bracket_generated ? `${tournament.current_round}/${tournament.total_rounds}` : 'Not started', color: 'text-purple-400', bg: 'bg-purple-500/10 border-purple-500/15' },
        ].map(s => (
          <div key={s.label} className={`p-3.5 rounded-xl border text-center ${s.bg}`}>
            <p className={`font-orbitron font-black text-xl ${s.color}`}>{s.val}</p>
            <p className="text-[10px] text-white/35 mt-0.5">{s.label}</p>
          </div>
        ))}
      </div>

      {/* Generate bracket button */}
      {!tournament.bracket_generated && tournament.status !== 'completed' && (
        <div className="mb-5 p-4 rounded-2xl bg-gradient-to-r from-cyan-500/8 to-purple-500/8 border border-cyan-500/20">
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <div>
              <p className="font-orbitron font-bold text-sm text-white">Ready to Generate Bracket?</p>
              <p className="text-xs text-white/40 mt-0.5">{checkedIn} players checked in · {participants.filter(p => p.status === 'joined').length} still registered</p>
            </div>
            <button onClick={generateBracket} disabled={generatingBracket || checkedIn < 2}
              className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-gradient-to-r from-cyan-500 to-purple-600 text-white text-sm font-bold hover:opacity-90 transition-all disabled:opacity-50">
              {generatingBracket ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
              Generate Bracket
            </button>
          </div>
          {checkedIn < 2 && <p className="text-[10px] text-yellow-400 mt-2">⚠ Need at least 2 checked-in players to generate bracket.</p>}
        </div>
      )}

      {/* Tabs */}
      <div className="flex border-b border-white/8 mb-5 overflow-x-auto">
        {TABS.map(t => (
          <button key={t.id} onClick={() => setTab(t.id)}
            className={`flex items-center gap-1.5 px-4 py-2.5 text-xs font-semibold whitespace-nowrap transition-all border-b-2 -mb-px ${
              tab === t.id ? 'text-cyan-400 border-cyan-400' : 'text-white/40 border-transparent hover:text-white/60'
            }`}>
            <t.icon className="w-3.5 h-3.5" />{t.label}
          </button>
        ))}
        <div className="ml-auto flex items-center">
          <button onClick={load} disabled={loading} className="text-white/30 hover:text-white/60 transition-colors p-2">
            <RefreshCw className={'w-3.5 h-3.5 ' + (loading ? 'animate-spin' : '')} />
          </button>
        </div>
      </div>

      {/* Tab content */}
      {tab === 'overview' && (
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-3 text-sm">
            {[
              ['Entry Fee', `${tournament.entry_fee} PP`],
              ['Prize Pool', `${tournament.prize_amount} PP`],
              ['Bracket', tournament.bracket_generated ? '✓ Generated' : 'Pending'],
              ['Format', tournament.easy_mode ? '⚡ Easy Mode' : 'Standard'],
            ].map(([k, v]) => (
              <div key={k} className="p-3.5 rounded-xl bg-white/4 border border-white/8">
                <p className="text-[10px] text-white/35 uppercase tracking-wider">{k}</p>
                <p className="font-semibold text-white mt-0.5">{v}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {tab === 'participants' && (
        <div className="space-y-2">
          {participants.map((p, i) => (
            <motion.div key={p.id} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.02 }}
              className={`flex items-center gap-3 p-3.5 rounded-xl border transition-all group ${
                p.status === 'checked_in' ? 'bg-green-500/5 border-green-500/15' :
                p.status === 'dropped' ? 'bg-white/2 border-white/6 opacity-60' :
                'bg-white/3 border-white/8'
              }`}>
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-cyan-500 to-purple-600 flex items-center justify-center text-white text-xs font-orbitron font-black flex-shrink-0">
                {p.profiles?.username?.[0]?.toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                  <p className="text-sm font-semibold text-white">{p.profiles?.username}</p>
                  {p.in_game_username && <span className="text-[10px] text-white/30">({p.in_game_username})</span>}
                </div>
                <p className="text-[10px] text-white/30 capitalize">{p.status}</p>
              </div>
              {p.seed && <span className="text-[10px] font-mono text-white/25">Seed #{p.seed}</span>}
              {p.status !== 'dropped' && (
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={() => toggleCheckIn(p)} title={p.status === 'checked_in' ? 'Undo check-in' : 'Force check-in'}
                    className={`p-1.5 rounded-lg transition-all ${p.status === 'checked_in' ? 'hover:bg-yellow-500/20 text-yellow-400' : 'hover:bg-green-500/20 text-white/30 hover:text-green-400'}`}>
                    <UserCheck className="w-3.5 h-3.5" />
                  </button>
                  <button onClick={() => eliminatePlayer(p)} title="Eliminate / Remove"
                    className="p-1.5 rounded-lg hover:bg-red-500/20 text-white/25 hover:text-red-400 transition-all">
                    <UserX className="w-3.5 h-3.5" />
                  </button>
                </div>
              )}
            </motion.div>
          ))}
        </div>
      )}

      {tab === 'matches' && (
        <div className="space-y-2">
          {matches.filter(m => !m.is_bye).map((m, i) => (
            <motion.div key={m.id} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.02 }}
              className="flex items-center gap-3 p-3.5 rounded-xl bg-white/3 border border-white/8 group">
              <div className="w-8 h-8 rounded-xl bg-white/6 flex items-center justify-center flex-shrink-0 text-xs font-mono text-white/40">
                #{m.match_number}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5 text-sm">
                  <span className={`font-semibold ${m.winner_id === m.player1_id ? 'text-green-400' : 'text-white/70'}`}>{m.player1?.username ?? 'TBD'}</span>
                  <span className="text-white/20">vs</span>
                  <span className={`font-semibold ${m.winner_id === m.player2_id ? 'text-green-400' : 'text-white/70'}`}>{m.player2?.username ?? 'TBD'}</span>
                </div>
                <span className={`text-[10px] capitalize font-mono ${
                  m.status === 'disputed' ? 'text-red-400' :
                  m.status === 'awaiting_proof' ? 'text-yellow-400' :
                  m.status === 'settled' || m.status === 'verified' ? 'text-green-400/60' :
                  'text-white/30'
                }`}>Round {m.round} · {m.status.replace('_', ' ')}</span>
              </div>
              {/* Force advance if match is stuck */}
              {['scheduled','in_progress','awaiting_proof','disputed'].includes(m.status) && m.player1_id && m.player2_id && (
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  {[{ id: m.player1_id, label: m.player1?.username ?? 'P1' }, { id: m.player2_id, label: m.player2?.username ?? 'P2' }].map(p => (
                    <button key={p.id} onClick={() => forceAdvance(m.id, p.id)} disabled={advancingMatch === m.id}
                      title={`Force win for ${p.label}`}
                      className="px-2 py-1 rounded-lg bg-yellow-500/15 border border-yellow-500/25 text-yellow-400 text-[10px] font-bold hover:bg-yellow-500/25 transition-all flex items-center gap-1">
                      {advancingMatch === m.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <Crown className="w-3 h-3" />}
                      {p.label.split(' ')[0]}
                    </button>
                  ))}
                </div>
              )}
            </motion.div>
          ))}
          {matches.filter(m => !m.is_bye).length === 0 && (
            <div className="text-center py-12 text-white/30 text-sm">No matches yet — generate bracket first.</div>
          )}
        </div>
      )}

      {tab === 'disputes' && (
        <div className="space-y-3">
          {disputes.length === 0 ? (
            <div className="text-center py-12">
              <CheckCircle className="w-10 h-10 mx-auto text-white/15 mb-3" />
              <p className="text-white/30 text-sm">No disputes — the tournament is clean!</p>
            </div>
          ) : disputes.map((d, i) => {
            const match = matches.find(m => m.id === d.match_id);
            return (
              <motion.div key={d.id} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.04 }}
                className={`p-4 rounded-xl border ${d.state === 'open' ? 'bg-red-500/6 border-red-500/20' : 'bg-white/3 border-white/8'}`}>
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full border font-bold ${d.state === 'open' ? 'bg-red-500/20 text-red-400 border-red-500/30' : 'bg-white/8 text-white/35 border-white/15'}`}>{d.state}</span>
                      {match && <span className="text-[10px] text-white/30">Match #{match.match_number}</span>}
                    </div>
                    <p className="text-sm text-white/70">{d.reason}</p>
                    <p className="text-[10px] text-white/30 mt-1">by @{d.opened_by_profile?.username ?? '—'}</p>
                  </div>
                  {d.state === 'open' && match && match.player1_id && match.player2_id && (
                    <div className="flex flex-col gap-1.5 flex-shrink-0">
                      <p className="text-[9px] text-white/25 text-center">Force win for:</p>
                      {[{ id: match.player1_id, label: match.player1?.username }, { id: match.player2_id, label: match.player2?.username }].map(p => (
                        <button key={p.id} onClick={() => resolveDispute(d.id, p.id, d.match_id)}
                          className="px-2.5 py-1.5 rounded-lg bg-yellow-500/15 border border-yellow-500/25 text-yellow-400 text-[10px] font-bold hover:bg-yellow-500/25 transition-all">
                          {p.label ?? p.id.slice(0, 6)}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </motion.div>
            );
          })}
        </div>
      )}
    </div>
  );
}

